// Vocabulary lessons seed — merged from 4 separate one-off scripts (each
// already run against the live DB): 7 IELTS Speaking cue-card topic
// lessons, 17 IELTS Speaking topic vocab/collocation lessons, and the
// Mindset 0 / Mindset 1 course vocab (10 and 8 units respectively, grouped
// 2 units per lesson). Each keeps its own data and its own seed function
// exactly as originally written — only the shared ADMIN_EMAIL/toWordDoc()/
// dedupeWords() helpers (byte-identical across all 4 originals) and the
// requires/dotenv/connect-disconnect boilerplate were consolidated.
// Run: node backend/scripts/seedVocabLessons.js
'use strict';
const ADMIN_EMAIL = 'tranhadeeptry@gmail.com'; // existing admin — createdBy

function toWordDoc([word, meaning, example, definition]) {
  return { word, meaning, example, definition, ipa: '', partOfSpeech: '', collocations: [], distractors: [] };
}

// A handful of general phrases can recur across adjacent source lists —
// drop later repeats so a single lesson never quizzes the same word twice.
function dedupeWords(entries) {
  const seen = new Set();
  return entries.filter(([word]) => {
    const key = word.trim().toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

// One-time content backfill — 7 cross-topic vocabulary lessons_CueCard covering the
