// A handful of general phrases can recur across adjacent units' own source
// lists — drop later repeats so a single lesson never quizzes the same
// word twice.

async function runSeedMindset1() {
  const VocabularyLesson = require('../models/VocabularyLesson');
  const User = require('../models/User');

  const admin = await User.findOne({ email: ADMIN_EMAIL }).select('_id').lean();
  if (!admin) throw new Error(`Admin user not found: ${ADMIN_EMAIL}`);

  for (const lesson of lessons_Mindset1) {
    const existing = await VocabularyLesson.findOne({ title: lesson.title }).lean();
    if (existing) {
      console.log(`[SeedVocabMindset1] "${lesson.title}" already exists (_id=${existing._id}) – skip`);
      continue;
    }
    const doc = await VocabularyLesson.create({
      title: lesson.title,
      description: lesson.description,
      difficulty: lesson.difficulty,
      order: lesson.order,
      targetClass: '',
      published: false, // review before publishing to students
      createdBy: admin._id,
      words: lesson.words.map(toWordDoc),
    });
    console.log(`[SeedVocabMindset1] Inserted "${doc.title}" (_id=${doc._id}, ${doc.words.length} words)`);
  }
}


async function runSeed() {
  await runSeedCueCard();
  await runSeedIeltsSpeaking();
  await runSeedMindset0();
  await runSeedMindset1();
}

if (require.main === module) {
  require('dotenv').config();
  const mongoose = require('mongoose');
  (async () => {
    await mongoose.connect(process.env.MONGO_URI);
    try {
      await runSeed();
    } finally {
      await mongoose.disconnect();
    }
  })().catch(e => { console.error('[SeedVocabLessons] FAILED', e); process.exit(1); });
}

module.exports = {
  runSeed,
  runSeedCueCard, runSeedIeltsSpeaking, runSeedMindset0, runSeedMindset1,
  lessons_CueCard, lessons_IeltsSpeaking, lessons_Mindset0, lessons_Mindset1,
};
